SELECT evidence - 'readOnly' AS catalog FROM (WITH targets AS (SELECT c.* FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('users','tenants','students','party_parties','party_relationships','edu_courses','edu_enrollments','org_units','user_org_unit_access','edu_attendance','edu_attendance_daily_state','edu_daily_care_sessions','edu_daily_care_records','preschool_chain_course_branch_assignments','preschool_school_announcements','people_directory','org_relationships','persons','audit_logs'))
 SELECT jsonb_build_object('readOnly',current_setting('transaction_read_only'),'database',current_database(),'serverVersion',current_setting('server_version_num'),
 'relations',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',relname,'kind',relkind,'owner',pg_get_userbyid(relowner),'acl',(SELECT array_agg(acl_item::text ORDER BY acl_item::text)::text FROM unnest(relacl) acl_item),'rls',relrowsecurity,'forceRls',relforcerowsecurity,'definition',CASE WHEN relkind='v' THEN pg_get_viewdef(oid,true) ELSE NULL END) ORDER BY relname),'[]') FROM targets),
 'columns',(SELECT coalesce(jsonb_agg(jsonb_build_object('relation',c.relname,'name',a.attname,'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'acl',(SELECT array_agg(acl_item::text ORDER BY acl_item::text)::text FROM unnest(a.attacl) acl_item),'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY c.relname,a.attnum),'[]') FROM targets c JOIN pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('relation',c.relname,'name',n.conname,'definition',pg_get_constraintdef(n.oid,true)) ORDER BY c.relname,n.conname),'[]') FROM targets c JOIN pg_constraint n ON n.conrelid=c.oid),
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('relation',tablename,'name',policyname,'roles',roles,'command',cmd,'permissive',permissive,'using',qual,'check',with_check) ORDER BY tablename,policyname),'[]') FROM pg_policies WHERE schemaname='public' AND tablename IN ('users','tenants','students','party_parties','party_relationships','edu_courses','edu_enrollments','org_units','user_org_unit_access','edu_attendance','edu_attendance_daily_state','edu_daily_care_sessions','edu_daily_care_records','preschool_chain_course_branch_assignments','preschool_school_announcements','people_directory','org_relationships','persons','audit_logs')),
 'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_object('relation',tablename,'name',indexname,'definition',indexdef) ORDER BY tablename,indexname),'[]') FROM pg_indexes WHERE schemaname='public' AND tablename IN ('users','tenants','students','party_parties','party_relationships','edu_courses','edu_enrollments','org_units','user_org_unit_access','edu_attendance','edu_attendance_daily_state','edu_daily_care_sessions','edu_daily_care_records','preschool_chain_course_branch_assignments','preschool_school_announcements','people_directory','org_relationships','persons','audit_logs')),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('relation',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'function',t.tgfoid::regprocedure::text) ORDER BY c.relname,t.tgname),'[]') FROM targets c JOIN pg_trigger t ON t.tgrelid=c.oid WHERE NOT t.tgisinternal),
 'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'acl',(SELECT array_agg(acl_item::text ORDER BY acl_item::text)::text FROM unnest(p.proacl) acl_item),'definition',pg_get_functiondef(p.oid),'md5',md5(pg_get_functiondef(p.oid))) ORDER BY p.oid::regprocedure::text),'[]') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('edu_preschool_enrollment_candidates','edu_preschool_enroll_student','preschool_portal_issuer_context','preschool_portal_daily_read','preschool_publish_school_announcement','preschool_list_school_announcements','preschool_portal_school_announcements_read','preschool_save_care_records','edu_preschool_roster_identity','edu_set_daily_attendance','edu_attendance_can_read_course','edu_can_access_attendance_enrollment','edu_course_catalog_actor_allowed','get_auth_tenant_id','current_tenant_id','current_user_role','log_audit_event','sync_user_claims_to_auth')),
 'schemas',(SELECT jsonb_agg(jsonb_build_object('name',nspname,'acl',nspacl::text) ORDER BY nspname) FROM pg_namespace WHERE nspname IN ('public','auth')),
 'defaultAcls',(SELECT coalesce(jsonb_agg(jsonb_build_object('role',defaclrole::regrole::text,'schema',defaclnamespace::regnamespace::text,'kind',defaclobjtype,'acl',defaclacl::text) ORDER BY defaclrole,defaclnamespace,defaclobjtype),'[]') FROM pg_default_acl),
 'memberships',(SELECT jsonb_agg(jsonb_build_object('role',roleid::regrole::text,'member',member::regrole::text,'admin',admin_option) ORDER BY roleid,member) FROM pg_auth_members)) AS evidence) catalog_snapshot;
